//! Rotosolve: coordinate-wise optimisation with the closed-form optimum of a
//! single-frequency sinusoid, reusing the predicted optimum as Nakanishi,
//! Fujii and Todo do.
//!
//! References:
//!
//! - M. Ostaszewski, E. Grant and M. Benedetti, "Structure optimization for
//!   parameterized quantum circuits", Quantum 5, 391 (2021),
//!   doi:10.22331/q-2021-01-28-391, arXiv:1905.09692: when a parameter is the
//!   angle of one rotation generated by a Pauli operator, the expectation is a
//!   sinusoid of it, whose optimum three evaluations give in closed form
//!   (Rotosolve); one parameter after another, sweep after sweep.
//! - K. M. Nakanishi, K. Fujii and S. Todo, "Sequential minimal optimization
//!   for quantum-classical hybrid algorithms", Phys. Rev. Research 2, 043158
//!   (2020), doi:10.1103/PhysRevResearch.2.043158, arXiv:1903.12166: the same
//!   sinusoidal step (NFT), with the value of the sinusoid at its optimum
//!   reused as the value of the new point, so a step needs two new
//!   evaluations, and the point itself measured again from time to time.
//!
//! The update below is written for this crate's convention, maximisation
//! (contract C-5); the papers minimise, and their optimum is the opposite point
//! of the circle. It behaves as PennyLane's `RotosolveOptimizer` with one
//! frequency and Qiskit's `NFT` do, without taking their code.

use crate::error::OptimizerError;
use crate::objective::EvaluationOracle;
use crate::observer::{IterationObserver, IterationReport};
use crate::outcome::{OptimizationOutcome, Optimizer};
use crate::rng::with_seeded_rng;
use crate::util::{
    check_initial_point, check_oracle_len, measure_last_point, wrap_angle, BestMeasured,
};
use rand::{Rng, RngExt};
use std::f64::consts::{FRAC_PI_2, TAU};

/// Rotosolve (Ostaszewski, Grant and Benedetti, 2021) with the value reuse of
/// Nakanishi, Fujii and Todo (2020).
///
/// It applies when every parameter is the angle of one rotation generated by a
/// single Pauli operator, as `±θ + c`, and the fitness is linear in the
/// measured distribution (a cost per bitstring averaged over the shots). Then,
/// with the other parameters fixed, the fitness is a sinusoid of each
/// parameter, `f(θ_j + t) = a + A·cos t + B·sin t`, whose maximum three values
/// give in closed form. This crate cannot check that structure: the caller
/// does (`polypus-circuit`'s `check_single_frequency`). On another landscape
/// the step is not an optimum, and the run is a heuristic.
///
/// # The step
///
/// Step `k = 0, 1, …` updates parameter `j = k mod d` of the current point
/// `x`. With `f₀ = f(x)`, `f₊ = f(x + π/2·e_j)` and `f₋ = f(x − π/2·e_j)`:
/// `a = (f₊ + f₋)/2`, `B = (f₊ − f₋)/2`, `A = f₀ − a`, and the maximum along
/// the coordinate is at `x_j + atan2(B, A)`, with value `a + √(A² + B²)`. The
/// new coordinate is wrapped into `[0, 2π)` (the fitness is 2π-periodic in
/// each such parameter); the others are left as they are, so an
/// [`initial_point`](AlgorithmRotosolveArgs::initial_point) outside `[0, 2π)`
/// is wrapped one coordinate at a time. A flat coordinate (`A = B = 0`) does
/// not move.
///
/// # One batch per step, with NFT's value reuse
///
/// Each step is **one** `evaluate_batch`: `[x + π/2·e_j, x − π/2·e_j]`, headed
/// by `x` itself (three candidates) on the first step and every
/// [`reevaluate_every`](AlgorithmRotosolveArgs::reevaluate_every) steps
/// (`k mod reevaluate_every == 0`). When `x` is measured, `f₀` is its value;
/// otherwise `f₀` is the previous step's predicted maximum `a + √(A² + B²)`,
/// which without noise is exactly `f(x)`. Re-measuring `x` stops shot noise
/// from accumulating in the chain of predictions; `reevaluate_every = 1` is
/// plain Rotosolve, three circuits per step.
///
/// # What is measured (contract C-5)
///
/// `best_params` is the best of the measured points, `x` when it is measured
/// and every `x ± π/2·e_j`, offered in batch order (the first measurement,
/// then only a strictly better one, so a `NaN` never wins over a number: a
/// `NaN` first measurement is kept only until a number arrives), and
/// `best_fitness` the value the oracle returned for it. Predicted values
/// never compete. The neighbours are offered as they are, not wrapped, so
/// `best_params` can lie up to π/2 outside `[0, 2π)`, and further when an
/// `initial_point` outside it leaves a coordinate unmoved. `fitness_history` has one entry per step, the best measured
/// up to it; the first step measures θ₀, so no entry is the `-∞` of nothing
/// measured, and the last is `best_fitness`.
///
/// After the last step, whether the run used its sweeps or stopped early, one
/// more batch of one candidate measures the point it reached, which competes
/// for `best_params` like any measured point; its value joins the last entry
/// of `fitness_history`. The stop is decided before it, so that entry can be
/// higher than the one the stop judged. It is measured within the last step,
/// before an [`IterationObserver`](crate::IterationObserver) sees it; a run the
/// observer stops on an earlier step ends without measuring the point that
/// step reached, and reports `converged = false`.
///
/// When `f₀`, `f₊`, `f₋` or the step is not finite, the coordinate is left as
/// it is; the value of `x` is then unchanged, and a non-finite one stays until
/// `x` is measured again.
///
/// # Stopping, in whole sweeps
///
/// A sweep is `d` steps, every parameter once. With `B₀` the value measured
/// for θ₀ and `B_s` the best measured value at the end of sweep `s`, the
/// improvement of sweep `s` is `B_s − B_{s−1}`. The run stops at the end of
/// the sweep that makes [`patience`](AlgorithmRotosolveArgs::patience)
/// consecutive sweeps with an improvement below
/// [`tolerance`](AlgorithmRotosolveArgs::tolerance) (a larger or non-finite
/// one resets the count), and reports `converged = true`; otherwise it runs
/// [`sweeps`](AlgorithmRotosolveArgs::sweeps) sweeps and reports
/// `converged = false`. `tolerance = 0` never stops early. `iterations_run`
/// counts steps.
///
/// # Reproducibility
///
/// The seed only draws θ₀, uniformly from `[0, 2π)`; the parameters are
/// visited in order. The step calls `atan2` and `hypot`, whose last bit Rust
/// leaves to the platform's math library, so a seeded run reproduces on the
/// same platform and build, like [`AlgorithmCmaEs`](crate::AlgorithmCmaEs),
/// but may differ on another (contract C-7).
///
/// # Example
///
/// ```
/// use polypus_optimizers::{
///     AlgorithmRotosolve, AlgorithmRotosolveArgs, EvaluationOracle, Optimizer,
/// };
///
/// // Σ cos(xᵢ − 1): a sinusoid of each coordinate, maximised (value 3) at xᵢ = 1.
/// struct Cosines;
/// impl EvaluationOracle for Cosines {
///     fn evaluate_batch(&self, candidates: &[Vec<f64>]) -> Vec<f64> {
///         candidates
///             .iter()
///             .map(|c| c.iter().map(|x| (x - 1.0).cos()).sum())
///             .collect()
///     }
/// }
///
/// let outcome = AlgorithmRotosolve
///     .optimize(AlgorithmRotosolveArgs {
///         oracle: Box::new(Cosines),
///         sweeps: 10,
///         // Every sweep starts by measuring the point.
///         reevaluate_every: 3,
///         tolerance: 1e-9,
///         patience: 1,
///         dimensions: 3,
///         seed: Some(7),
///         initial_point: None,
///     })
///     .expect("valid arguments optimize successfully");
///
/// // Separable, so the first sweep reaches the optimum, the second measures
/// // it, and the third finds nothing better.
/// assert!(outcome.best_fitness > 3.0 - 1e-12, "fitness = {}", outcome.best_fitness);
/// assert!(outcome.converged);
/// assert_eq!(outcome.iterations_run, 3 * 3);
/// ```
pub struct AlgorithmRotosolve;

/// Arguments for [`AlgorithmRotosolve`].
///
/// # Preconditions
///
/// Checked before any RNG draw or oracle call, each violation an
/// [`OptimizerError::InvalidConfig`] naming the parameter, in this order:
/// `sweeps >= 1`, `dimensions >= 1`, `reevaluate_every >= 1`, `tolerance`
/// finite and `>= 0`, `patience >= 1`, and `initial_point`, when given,
/// `dimensions` finite values.
pub struct AlgorithmRotosolveArgs {
    /// Maps parameter vectors to fitness values (higher is better).
    pub oracle: Box<dyn EvaluationOracle>,
    /// Sweeps at most, each `dimensions` steps: every parameter once, in
    /// order.
    pub sweeps: u32,
    /// The current point heads its step's batch (three candidates instead of
    /// two) on the first step and every `reevaluate_every` steps.
    pub reevaluate_every: u32,
    /// The improvement of the best measured fitness over a sweep below which
    /// the sweep counts towards the stop, in the oracle's fitness units.
    pub tolerance: f64,
    /// Consecutive sweeps whose improvement is below `tolerance` that stop
    /// the run.
    pub patience: u32,
    /// Number of parameters.
    pub dimensions: u32,
    /// Optional RNG seed. `None` (the default) uses [`rand::rng`];
    /// `Some(seed)` makes the run reproducible.
    pub seed: Option<u64>,
    /// Optional θ₀, one value per dimension, all finite, taken as it is: it is
    /// the first candidate of the first batch. θ₀ is drawn from `[0, 2π)`
    /// either way and then replaced, so the RNG stream does not depend on it.
    /// `None` starts from the drawn θ₀.
    pub initial_point: Option<Vec<f64>>,
}

impl AlgorithmRotosolve {
    /// The optimizer's human-readable name.
    pub fn name(&self) -> String {
        String::from("Rotosolve")
    }

    /// A short description of the optimizer.
    pub fn description(&self) -> String {
        String::from(
            "Trains a variational quantum circuit whose parameters are each one \
             single-Pauli rotation with Rotosolve: one parameter at a time, it moves to the \
             maximum of the sinusoid through three values along it, in closed form, reusing \
             the predicted maximum as the next point's value so each step sends two \
             circuits. Stops early when sweeps stop improving the best measured fitness.",
        )
    }

    /// Check the preconditions of [`AlgorithmRotosolveArgs`] that
    /// [`optimize`](Optimizer::optimize) checks before any RNG draw or oracle
    /// call, in the same order, without running anything: the configuration
    /// listed on [`AlgorithmRotosolveArgs`], then `initial_point`
    /// (`dimensions` finite values). `train` and `qml.train` call it before
    /// any backend exists.
    pub fn check_preconditions(
        sweeps: u32,
        reevaluate_every: u32,
        tolerance: f64,
        patience: u32,
        dimensions: u32,
        initial_point: Option<&[f64]>,
    ) -> Result<(), OptimizerError> {
        validate(sweeps, dimensions, reevaluate_every, tolerance, patience)?;
        check_initial_point(initial_point, dimensions as usize, None)
    }

    /// Whether step `step` (from 0) measures the current point: the first,
    /// and every `reevaluate_every` after it.
    fn measures(step: u64, reevaluate_every: u32) -> bool {
        step % u64::from(reevaluate_every) == 0
    }

    fn run_with_rng<R: Rng>(
        args: AlgorithmRotosolveArgs,
        rng: &mut R,
        observer: &mut dyn IterationObserver,
    ) -> Result<OptimizationOutcome, OptimizerError> {
        let AlgorithmRotosolveArgs {
            oracle,
            sweeps,
            reevaluate_every,
            tolerance,
            patience,
            dimensions,
            seed: _,
            initial_point,
        } = args;

        Self::check_preconditions(
            sweeps,
            reevaluate_every,
            tolerance,
            patience,
            dimensions,
            initial_point.as_deref(),
        )?;
        let dims = dimensions as usize;
        // Draw θ₀ in [0, 2π), or start at the caller's point: θ₀ is drawn
        // either way, so the RNG stream does not depend on it.
        let drawn: Vec<f64> = (0..dims).map(|_| rng.random_range(0.0..TAU)).collect();
        let mut x = initial_point.unwrap_or(drawn);

        let mut best = BestMeasured::new();
        // Best measured fitness after each step (see
        // `OptimizationOutcome::fitness_history`).
        let mut fitness_history: Vec<f64> = Vec::new();
        // The value of `x`: measured, or the previous step's predicted maximum.
        let mut value = f64::NAN;
        // B_{s−1}: the best measured at the end of the previous sweep, θ₀'s
        // value before the first.
        let mut previous_best = f64::NAN;
        let mut stagnant = 0u32;
        let mut converged = false;
        let mut step = 0u64;

        'sweeps: for sweep in 1..=sweeps {
            for j in 0..dims {
                let measured = Self::measures(step, reevaluate_every);
                // ── 1. One batch: x when it is measured, then x ± π/2·e_j ──────
                let mut plus = x.clone();
                plus[j] += FRAC_PI_2;
                let mut minus = x.clone();
                minus[j] -= FRAC_PI_2;
                let mut batch = Vec::with_capacity(2 + usize::from(measured));
                if measured {
                    batch.push(x.clone());
                }
                batch.push(plus);
                batch.push(minus);
                let values = oracle.evaluate_batch(&batch);
                check_oracle_len(batch.len(), values.len())?;
                for (candidate, &v) in batch.iter().zip(&values) {
                    best.offer(candidate, v);
                }
                let shifted = if measured {
                    value = values[0];
                    if step == 0 {
                        previous_best = value;
                    }
                    &values[1..]
                } else {
                    &values[..]
                };

                // ── 2. Move to the maximum of the sinusoid through the three ───
                match sinusoid_maximum(value, shifted[0], shifted[1]) {
                    Some((shift, peak)) => {
                        x[j] = wrap_angle(x[j] + shift);
                        value = peak;
                    }
                    None => log::debug!(
                        "Step {step}: a value along parameter {j} is not finite \
                         (f = {value}, {}, {}); the parameter is left as it is",
                        shifted[0],
                        shifted[1]
                    ),
                }
                // The running best of the measured points: the first step
                // measures θ₀, so no entry is the `-∞` of nothing measured
                // (C-5).
                fitness_history.push(best.value());
                step += 1;

                // ── 3. After a sweep's last step, stop after `patience` sweeps
                // that improved too little ─────────────────────────────────────
                let mut last = false;
                if j + 1 == dims {
                    let sweep_best = best.value();
                    let improvement = sweep_best - previous_best;
                    previous_best = sweep_best;
                    log::debug!(
                        "Sweep {sweep}: best measured {sweep_best:.6}, improvement \
                         {improvement:.6}"
                    );
                    if improvement < tolerance {
                        stagnant += 1;
                    } else {
                        stagnant = 0;
                    }
                    if stagnant >= patience {
                        log::debug!(
                            "Stopping after sweep {sweep}: {stagnant} sweeps improved by less \
                             than {tolerance}"
                        );
                        converged = true;
                    }
                    last = converged || sweep == sweeps;
                }

                // ── 4. After the last step, measure the point it reached ───────
                // Before the report, so the observer sees the run's final best.
                if last {
                    let fitness =
                        measure_last_point(oracle.as_ref(), &x, &mut best, &mut fitness_history)?;
                    log::debug!("Final point: fitness {fitness:.4}");
                }

                // ── 5. Report; a stop asked for here wins over the sweeps' stop ─
                let report = IterationReport {
                    iteration: fitness_history.len(),
                    best_fitness: best.value(),
                    best_params: best.params(),
                };
                if observer.observe(&report).is_break() {
                    // The point this step reached stays unmeasured, unless this
                    // was the last step anyway.
                    converged = false;
                    break 'sweeps;
                }
                if last {
                    break 'sweeps;
                }
            }
        }

        // `sweeps >= 1`, `dimensions >= 1` and the first step measures θ₀, so
        // `best` holds a measured point.
        let (best_params, best_fitness) = best.into_parts();
        Ok(OptimizationOutcome {
            best_params,
            best_fitness,
            iterations_run: fitness_history.len(),
            converged,
            fitness_history,
        })
    }
}

/// The maximum of the sinusoid `a + A·cos t + B·sin t` through
/// `f(θ) = value`, `f(θ + π/2) = plus` and `f(θ − π/2) = minus`: the shift `t`
/// from θ to its arg max, in `[−π, π]`, and the value there,
/// `a + √(A² + B²)`. `None` when a value, the shift or the maximum is not
/// finite. A flat sinusoid (`A = B = 0`) does not move: `atan2(±0, −0)` would
/// be `±π`.
fn sinusoid_maximum(value: f64, plus: f64, minus: f64) -> Option<(f64, f64)> {
    // Halves first, so finite values cannot overflow.
    let mean = 0.5 * plus + 0.5 * minus;
    let sine = 0.5 * plus - 0.5 * minus;
    let cosine = value - mean;
    if !(mean.is_finite() && sine.is_finite() && cosine.is_finite()) {
        return None;
    }
    if cosine == 0.0 && sine == 0.0 {
        return Some((0.0, mean));
    }
    let shift = sine.atan2(cosine);
    let peak = mean + cosine.hypot(sine);
    (shift.is_finite() && peak.is_finite()).then_some((shift, peak))
}

/// Reject a configuration Rotosolve cannot run, before any RNG draw or oracle
/// call.
fn validate(
    sweeps: u32,
    dimensions: u32,
    reevaluate_every: u32,
    tolerance: f64,
    patience: u32,
) -> Result<(), OptimizerError> {
    let invalid = |parameter: &'static str, reason: String| {
        Err(OptimizerError::InvalidConfig { parameter, reason })
    };
    if sweeps == 0 {
        return invalid(
            "sweeps",
            "must be at least 1 (a sweep updates every parameter once)".to_string(),
        );
    }
    if dimensions == 0 {
        return invalid(
            "dimensions",
            "must be at least 1 (there is nothing to optimise)".to_string(),
        );
    }
    if reevaluate_every == 0 {
        return invalid(
            "reevaluate_every",
            "must be at least 1 (steps between measurements of the parameters)".to_string(),
        );
    }
    if !tolerance.is_finite() || tolerance < 0.0 {
        return invalid(
            "tolerance",
            format!("must be finite and >= 0, got {tolerance}"),
        );
    }
    if patience == 0 {
        return invalid(
            "patience",
            "must be at least 1 (sweeps that improve less than tolerance before the run \
             stops)"
                .to_string(),
        );
    }
    Ok(())
}

impl Optimizer for AlgorithmRotosolve {
    type Args = AlgorithmRotosolveArgs;

    fn optimize_observed(
        &self,
        args: Self::Args,
        observer: &mut dyn IterationObserver,
    ) -> Result<OptimizationOutcome, OptimizerError> {
        with_seeded_rng(args.seed, |rng| Self::run_with_rng(args, rng, observer))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_point_is_measured_first_and_every_interval() {
        let measured: Vec<u64> = (0..23)
            .filter(|&k| AlgorithmRotosolve::measures(k, 5))
            .collect();
        assert_eq!(measured, [0, 5, 10, 15, 20]);
        assert!((0..4).all(|k| AlgorithmRotosolve::measures(k, 1)));
        assert!(AlgorithmRotosolve::measures(0, u32::MAX));
        assert!(!AlgorithmRotosolve::measures(1, u32::MAX));
    }

    /// The closed form against a brute-force maximisation of random sinusoids:
    /// the shift lands on the grid's arg max to within its step, and the
    /// predicted maximum is the sinusoid's value there.
    #[test]
    fn the_shift_is_the_arg_max_of_a_random_sinusoid() {
        // A small deterministic generator, so the test needs no RNG.
        let mut state = 0x9e37_79b9_7f4a_7c15_u64;
        let mut uniform = |lo: f64, hi: f64| {
            state = state
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            lo + (hi - lo) * ((state >> 11) as f64 / (1u64 << 53) as f64)
        };
        const GRID: usize = 20_000;
        for _ in 0..500 {
            let (c0, c1, c2) = (uniform(-3.0, 3.0), uniform(-3.0, 3.0), uniform(-3.0, 3.0));
            let f = |t: f64| c0 + c1 * t.cos() + c2 * t.sin();
            let theta = uniform(-10.0, 10.0);
            let (shift, peak) =
                sinusoid_maximum(f(theta), f(theta + FRAC_PI_2), f(theta - FRAC_PI_2)).unwrap();
            assert!((-std::f64::consts::PI..=std::f64::consts::PI).contains(&shift));
            let new = theta + shift;
            let grid_best = (0..GRID)
                .map(|k| theta + TAU * k as f64 / GRID as f64)
                .max_by(|a, b| f(*a).total_cmp(&f(*b)))
                .unwrap();
            let gap =
                (new - grid_best + std::f64::consts::PI).rem_euclid(TAU) - std::f64::consts::PI;
            assert!(gap.abs() <= TAU / GRID as f64, "gap {gap}");
            assert!(f(new) >= f(grid_best) - 1e-12);
            assert!((peak - f(new)).abs() < 1e-12, "{peak} vs {}", f(new));
            // The amplitude is √(c1² + c2²), whatever θ.
            assert!((peak - (c0 + c1.hypot(c2))).abs() < 1e-12);
        }
    }

    #[test]
    fn the_shift_matches_the_papers_minimising_form_turned_half_a_circle() {
        // Ostaszewski et al.'s minimum: θ − π/2 − atan2(2f₀ − f₊ − f₋, f₊ − f₋).
        for (f0, fp, fm) in [(0.3, -0.2, 1.1), (-1.0, 0.5, 0.25), (2.0, 2.5, -0.5)] {
            let (shift, _) = sinusoid_maximum(f0, fp, fm).unwrap();
            let minimum = -FRAC_PI_2 - (2.0 * f0 - fp - fm).atan2(fp - fm);
            let apart = (shift - minimum).rem_euclid(TAU);
            assert!((apart - std::f64::consts::PI).abs() < 1e-12, "{apart}");
        }
    }

    #[test]
    fn a_flat_coordinate_does_not_move() {
        assert_eq!(sinusoid_maximum(0.5, 0.5, 0.5), Some((0.0, 0.5)));
        // −0.0 − 0.0 is −0.0, and atan2(0, −0) would be π.
        assert_eq!(sinusoid_maximum(-0.0, 0.0, 0.0), Some((0.0, 0.0)));
        assert_eq!(sinusoid_maximum(-0.0, -0.0, -0.0), Some((0.0, -0.0)));
    }

    #[test]
    fn a_non_finite_value_gives_no_step() {
        for (f0, fp, fm) in [
            (f64::NAN, 0.0, 1.0),
            (0.0, f64::NAN, 1.0),
            (0.0, 1.0, f64::INFINITY),
            (f64::NEG_INFINITY, 1.0, 0.0),
            // Finite values whose maximum overflows.
            (f64::MAX, -f64::MAX, -f64::MAX),
        ] {
            assert_eq!(sinusoid_maximum(f0, fp, fm), None, "{f0} {fp} {fm}");
        }
        // Large finite values whose sums would overflow without the halves.
        assert_eq!(
            sinusoid_maximum(f64::MAX, f64::MAX, f64::MAX),
            Some((0.0, f64::MAX))
        );
        let big = 0.4 * f64::MAX;
        assert!(sinusoid_maximum(big, big, -big).is_some());
    }
}
